function camelToSnake(str) {
  if (typeof str !== 'string') {
    throw new TypeError('Argument must be a string');
  }

  if (!/[A-Z]/.test(str)) {
    return str;
  }

  let result = '';
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const nextChar = str[i + 1];
    const prevChar = str[i - 1];

    const isUpper = /[A-Z]/.test(char);
    const isLower = /[a-z]/.test(char);
    const isDigit = /[0-9]/.test(char);

    if (isUpper && nextChar && /[a-z]/.test(nextChar)) {
      // Case 2: Upper followed by Upper then Lower (end of acronym)
      // Insert underscore before this upper letter
      result += '_' + char;
    } else if ((isLower || isDigit) && isUpper) {
      // Case 1: Lower/Digit followed by Upper
      result += '_' + char;
    } else {
      result += char;
    }
  }

  return result.toLowerCase();
}

module.exports = { camelToSnake };
