function topoSort(graph) {
  const allTasks = new Set();
  const inDegree = new Map();
  const adj = new Map();

  // Initialize all tasks
  for (const task of Object.keys(graph)) {
    allTasks.add(task);
    inDegree.set(task, 0);
    adj.set(task, []);
  }

  // Handle tasks that appear only in dependency lists
  for (const task of Object.keys(graph)) {
    const deps = graph[task];
    for (const dep of deps) {
      if (!allTasks.has(dep)) {
        allTasks.add(dep);
        inDegree.set(dep, 0);
        adj.set(dep, []);
      }
    }
  }

  // Build graph and calculate in-degrees
  for (const task of Object.keys(graph)) {
    const deps = graph[task];
    const seen = new Set();
    for (const dep of deps) {
      if (seen.has(dep)) continue;
      seen.add(dep);
      adj.get(dep).push(task);
      inDegree.set(task, inDegree.get(task) + 1);
    }
  }

  // Initialize queue with tasks having no dependencies, sorted by name
  const queue = [];
  for (const task of allTasks) {
    if (inDegree.get(task) === 0) {
      queue.push(task);
    }
  }
  queue.sort();

  const result = [];

  while (queue.length > 0) {
    // Pick the smallest task (queue is kept sorted)
    const task = queue.shift();
    result.push(task);

    const neighbors = adj.get(task);
    for (const neighbor of neighbors) {
      inDegree.set(neighbor, inDegree.get(neighbor) - 1);
      if (inDegree.get(neighbor) === 0) {
        // Insert in sorted order
        let inserted = false;
        for (let i = 0; i < queue.length; i++) {
          if (neighbor < queue[i]) {
            queue.splice(i, 0, neighbor);
            inserted = true;
            break;
          }
        }
        if (!inserted) {
          queue.push(neighbor);
        }
      }
    }
  }

  if (result.length !== allTasks.size) {
    throw new Error('Cycle detected in dependencies');
  }

  return result;
}

