def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    if not text:
        raise ValueError("empty string")

    # Define order and values
    order = ['d', 'h', 'm', 's']
    values = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}

    total_seconds = 0
    last_unit_index = len(order)  # Start higher than any valid index

    # Parse the string into parts
    i = 0
    while i < len(text):
        # Parse integer part
        start = i
        if text[i] in '+-':
            i += 1
            if i >= len(text) or not text[i].isdigit():
                raise ValueError("invalid number format")
        while i < len(text) and text[i].isdigit():
            i += 1
        if i == start or (start < i and text[start] in '+-'):
            # If we only had signs or nothing
            if start == i:
                raise ValueError("missing number")
            if text[start] in '+-':
                raise ValueError("signs not allowed")

        number_str = text[start:i]
        if not number_str:
            raise ValueError("missing number")

        # Check for decimal point
        if '.' in number_str or 'e' in number_str.lower():
            raise ValueError("decimals not allowed")

        number = int(number_str)

        # Parse unit
        if i >= len(text) or text[i] not in values:
            raise ValueError("missing unit")

        unit = text[i]
        i += 1

        # Check for repeated or out-of-order units
        unit_index = order.index(unit)
        if unit_index >= last_unit_index:
            raise ValueError("units must be in strictly descending order")
        last_unit_index = unit_index

        total_seconds += number * values[unit]

    if i != len(text):
        raise ValueError("unexpected characters at end")

    return total_seconds
