function expandRanges(spec) {
  if (typeof spec !== 'string') {
    throw new TypeError('spec must be a string');
  }

  const parts = spec.split(',');
  const result = new Set();

  for (const part of parts) {
    const trimmed = part.trim();
    if (trimmed === '') {
      throw new SyntaxError('Empty part in specification');
    }

    const dashIndex = trimmed.indexOf('-');
    if (dashIndex === -1) {
      // Single number
      const num = Number(trimmed);
      if (!Number.isFinite(num) || trimmed !== String(num)) {
        throw new SyntaxError(`Invalid number: ${trimmed}`);
      }
      if (num < 0 || !Number.isInteger(num)) {
        throw new SyntaxError(`Invalid number: ${trimmed}`);
      }
      result.add(num);
    } else {
      // Range
      const startStr = trimmed.substring(0, dashIndex);
      const endStr = trimmed.substring(dashIndex + 1);

      if (startStr === '' || endStr === '') {
        throw new SyntaxError(`Invalid range: ${trimmed}`);
      }

      const start = Number(startStr);
      const end = Number(endStr);

      if (!Number.isFinite(start) || !Number.isFinite(end)) {
        throw new SyntaxError(`Invalid range: ${trimmed}`);
      }

      if (startStr !== String(start) || endStr !== String(end)) {
        throw new SyntaxError(`Invalid range: ${trimmed}`);
      }

      if (start < 0 || end < 0 || !Number.isInteger(start) || !Number.isInteger(end)) {
        throw new SyntaxError(`Invalid range: ${trimmed}`);
      }

      if (start > end) {
        throw new RangeError(`Start of range greater than end: ${trimmed}`);
      }

      for (let i = start; i <= end; i++) {
        result.add(i);
      }
    }
  }

  return Array.from(result).sort((a, b) => a - b);
}

module.exports = { expandRanges };
