def parse_csv_line(line):
    if not isinstance(line, str):
        raise TypeError("line must be a string")

    fields = []
    i = 0
    n = len(line)

    while True:
        if i >= n:
            # End of line reached
            if len(fields) == 0:
                # Empty line -> one empty field
                fields.append("")
            break

        # Start of a field
        if line[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # Escaped quote
                        field_chars.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                raise ValueError("Unclosed quoted field")

            fields.append("".join(field_chars))

            # After closing quote, must be comma or end of line
            if i < n and line[i] != ',':
                raise ValueError("Invalid character after quoted field")
        else:
            # Unquoted field: read until comma or end of line
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

        # Check if there is a comma to continue
        if i < n and line[i] == ',':
            i += 1  # skip comma and continue to next field
        else:
            # End of line
            break

    return fields
