      key = keyFn(...args);
    } else {
      key = args[0];
    }

    if (cache.has(key)) {
      return cache.get(key);
    }

    let result;
    try {
      result = fn.apply(this, args);
    } catch (error) {
      // Do not cache on error; rethrow
      throw error;
    }

    cache.set(key, result);
    return result;
