def is_balanced(code):
    stack = []
    i = 0
    n = len(code)

    while i < n:
        char = code[i]

        if char == '"':
            # Start of a string literal
            i += 1
            while i < n:
                if code[i] == '"':
                    # End of string
                    i += 1
                    break
                elif code[i] == '\\' and i + 1 < n:
                    # Escaped character, skip both
                    i += 2
                else:
                    i += 1
            else:
                # String never closed
                return False
            continue

        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack:
                return False
            top = stack.pop()
            if char == ')' and top != '(':
                return False
            if char == '}' and top != '{':
                return False
            if char == ']' and top != '[':
                return False

        i += 1

    return len(stack) == 0
