        mid_val = nums[mid]

        if mid_val == target:
            return mid

        # Determine which side is sorted
        if nums[left] <= mid_val:
            # Left side is sorted
            if nums[left] <= target < mid_val:
                right = mid - 1
            else:
                left = mid + 1
