def maze_steps(grid: List[str]) -> int:
    if not grid:
        raise ValueError("Grid must not be empty")

    row_len = len(grid[0])
    valid_chars = {'S', 'E', '#', '.'}
    start = None
    end = None
    count_s = 0
    count_e = 0

    for r, row in enumerate(grid):
        if len(row) != row_len:
            raise ValueError("All rows must have the same length")
        for c, ch in enumerate(row):
            if ch not in valid_chars:
                raise ValueError(f"Invalid character '{ch}' in grid")
            if ch == 'S':
                count_s += 1
                start = (r, c)
            elif ch == 'E':
                count_e += 1
                end = (r, c)

    if count_s != 1 or count_e != 1:
        raise ValueError("There must be exactly one 'S' and exactly one 'E'")

    if start is None or end is None:
        raise ValueError("Start or exit not found")

    rows = len(grid)
    cols = row_len
    visited = [[False] * cols for _ in range(rows)]
    queue = deque()
    queue.append((start[0], start[1], 0))
    visited[start[0]][start[1]] = True

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c, dist = queue.popleft()
        if (r, c) == end:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited[nr][nc] and grid[nr][nc] != '#':
                    visited[nr][nc] = True
                    queue.append((nr, nc, dist + 1))

    return -1
